      if (e.t === 'found' && cyc) { const id = g.edges.findIndex(x => (x.u === path[path.length - 1] && x.v === path[0]) || (!g.directed && x.u === path[0] && x.v === path[path.length - 1])); if (id >= 0) deco.e[id] = { color: col.green, width: 4.5 }; }
