  q(c14, '.go').onclick = DM.guard(() => { const n = DM.int(q(c14, '.n').value, 'n', 3, 12), t = TYPES[+q(c14, '.ty').value]; if (t[0] === 'reg' && n % 2) throw new Error('A 3-regular graph needs an even number of vertices.'); ed.set(t[2](n)); });

