  c15.querySelectorAll('.e1,.e2').forEach(i => i.oninput = ops); q(c15, '.pr').onchange = () => { const p = PR[+q(c15, '.pr').value]; q(c15, '.e1').value = p[0]; q(c15, '.e2').value = p[1]; ops(); }; ops();

